<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/governance.php';$pageTitle='Rechtliche Informationen';
$code=is_string($_GET['document']??null)?$_GET['document']:'';$language=is_string($_GET['language']??null)?$_GET['language']:'de';
if(!preg_match('/\A[a-z]{2}(?:-[A-Z]{2})?\z/',$language))abort_request(400,'Ungültige Dokumentsprache.');
$enabled=site_setting($pdo,'legal_publication_enabled','0')==='1';$selected=null;$error='';
$versionId=null;
if(array_key_exists('version_id',$_GET)){$versionId=is_string($_GET['version_id'])?filter_var($_GET['version_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]):false;if($versionId===false||$code==='')abort_request(400,t('consent.changed'));}
if($code!==''&&(!preg_match('/\A[a-z0-9-]{2,80}\z/',$code)||!$enabled))abort_request(503,'Diese Rechtsdokumente sind noch nicht zur produktiven Veröffentlichung freigegeben.');
if($code!==''){$q=$pdo->prepare("SELECT * FROM market_legal_documents WHERE document_code=? AND language=? AND status='approved' AND effective_at<=UTC_TIMESTAMP()".($versionId!==null?' AND id=?':'')." ORDER BY effective_at DESC,id DESC LIMIT 1");$q->execute($versionId!==null?[$code,$language,$versionId]:[$code,$language]);$selected=$q->fetch();if(!$selected)abort_request(404,'Für diese Sprache liegt noch keine gültige freigegebene Fassung vor.');try{consent_integrity($selected);}catch(DomainException $e){abort_request(503,$e->getMessage());}}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_csrf();$user=require_login($pdo);try{if(!$selected||post_string('accept_document')!=='1')throw new InvalidArgumentException('Bitte die angezeigte Fassung ausdrücklich bestätigen.');if(post_string('document_id')!==(string)$selected['id']||!hash_equals($selected['content_hash'],post_string('document_hash',64)))throw new InvalidArgumentException(t('consent.changed'));legal_accept($pdo,(int)$user['id'],(int)$selected['id'],'updated_terms');redirect('/marketplace/legal.php?document='.rawurlencode($code).'&language='.rawurlencode($language).'&version_id='.(int)$selected['id'].'&accepted=1');}catch(InvalidArgumentException|DomainException $e){http_response_code(422);$error=$e->getMessage();}}
if($selected&&($_GET['download']??'')==='1'){header('Content-Type: text/plain; charset=utf-8');header('Content-Disposition: attachment; filename="gunindex-'.$selected['document_code'].'-'.$selected['version'].'.txt"');echo$selected['body_text'];exit;}
$documents=$enabled?$pdo->query("SELECT d.id,d.document_code,d.language,d.title,d.version FROM market_legal_documents d WHERE d.status='approved' AND d.effective_at<=UTC_TIMESTAMP() AND NOT EXISTS(SELECT 1 FROM market_legal_documents n WHERE n.document_code=d.document_code AND n.language=d.language AND n.status='approved' AND n.effective_at<=UTC_TIMESTAMP() AND (n.effective_at>d.effective_at OR (n.effective_at=d.effective_at AND n.id>d.id))) ORDER BY d.title,d.language LIMIT 200")->fetchAll():[];
include __DIR__.'/../includes/header.php';?>
<main class="container"><div class="page-heading"><p class="eyebrow">Nachlesen und speichern</p><h1>Rechtliche Informationen.</h1><p>Es gelten die ausdrücklich freigegebenen Dokumentfassungen für den jeweiligen Vertrag. Eine spätere Änderung schreibt frühere Zustimmungen nicht um.</p></div>
<?php if(!$enabled):?><section class="panel"><h2>Fachliche Prüfung ausstehend</h2><p>Die vollständigen Betreiber- und Vertragsdokumente sind noch nicht zur produktiven Verwendung freigegeben. Es wird keine anwaltliche Prüfung behauptet.</p></section><?php endif;?>
<?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif;?><?php if($selected):?><section class="panel"><h2><?=h($selected['title'])?></h2><p>Version <?=h($selected['version'])?> · <?=h($selected['language'])?> · gültig ab <?=h($selected['effective_at'])?> UTC</p><p><a class="button secondary" href="?document=<?=h(rawurlencode($code))?>&amp;language=<?=h(rawurlencode($language))?>&amp;version_id=<?=(int)$selected['id']?>&amp;download=1">Fassung herunterladen</a></p><div style="white-space:pre-wrap;overflow-wrap:anywhere"><?=h($selected['body_text'])?></div><p>Dokumenthash SHA-256: <code><?=h($selected['content_hash'])?></code></p>
<?php if(current_user($pdo)):?><form method="post"><?=csrf_field()?><input type="hidden" name="document_id" value="<?=(int)$selected['id']?>"><input type="hidden" name="document_hash" value="<?=h($selected['content_hash'])?>"><label><input type="checkbox" name="accept_document" value="1" required> Ich bestätige diese angezeigte Dokumentfassung ausdrücklich.</label><button class="button" type="submit">Zustimmung speichern</button></form><?php endif;?><?php if(isset($_GET['accepted'])):?><p class="notice success">Die Zustimmung zu dieser Fassung wurde gespeichert.</p><?php endif;?></section><?php endif;?>
<section class="panel"><h2>Verfügbare Fassungen</h2><?php foreach($documents as $doc):?><p><a href="?document=<?=h(rawurlencode($doc['document_code']))?>&amp;language=<?=h(rawurlencode($doc['language']))?>"><?=h($doc['title'])?> · <?=h($doc['version'])?> / <?=h($doc['language'])?></a></p><?php endforeach;?><?php if(!$documents):?><p>Noch keine freigegebenen Fassungen vorhanden.</p><?php endif;?></section></main><?php include __DIR__.'/../includes/footer.php';?>
